//! The API's protobuf types (`caas.crypto.v1`), generated by build.rs from
//! the descriptor citius-c-api pins, with protobuf-JSON support (pbjson).
//! Shared vocabulary like Go's citius-api-go: the domain may use it.

#[allow(clippy::all, clippy::pedantic, missing_docs, dead_code, non_camel_case_types)]
pub mod caas {
    pub mod crypto {
        pub mod v1 {
            include!(concat!(env!("OUT_DIR"), "/proto/caas.crypto.v1.rs"));
            include!(concat!(env!("OUT_DIR"), "/proto/caas.crypto.v1.serde.rs"));
        }
    }
}

pub use caas::crypto::v1 as api;

#[cfg(test)]
mod tests {
    use super::api::TemplateInfo;
    use std::collections::BTreeMap;

    #[derive(serde::Deserialize)]
    struct Catalog {
        templates: BTreeMap<String, TemplateInfo>,
    }

    #[test]
    fn embedded_catalog_parses_into_the_api_types() {
        let catalog: Catalog =
            serde_json::from_str(include_str!("../../catalog/standard_algorithms.json")).expect("catalog parses");
        assert_eq!(catalog.templates.len(), 72);
        for (id, t) in &catalog.templates {
            assert_eq!(&t.template_id, id, "map key and templateId agree");
            assert!(!t.scoped_capabilities.is_empty(), "{id} has no scoped capabilities");
            assert!(t.algorithm.is_some(), "{id} has no algorithm");
        }
    }
}

#[cfg(test)]
mod strictness {
    use super::api::TemplateInfo;

    #[test]
    fn unknown_fields_are_rejected_not_dropped() {
        // A catalog newer than the descriptor must fail loudly, not load
        // with the fields this library does not know silently missing.
        let r: Result<TemplateInfo, _> = serde_json::from_str(r#"{"templateId":"x","notAField":1}"#);
        assert!(r.is_err());
    }
}
